/* Illustrated, touch-sized field notes. Illustrations are original UI vectors. */
const LIFE_TABS34=[['today','Today'],['almanac','Almanac'],['garden','Garden'],['market','Finds'],['people','People'],['home','Home']];
function lifeSVG34(inner){return `<svg viewBox="0 0 100 80" aria-hidden="true">${inner}</svg>`;}
function fishIcon34(f){return lifeSVG34(`<path d="M18 41C32 12 66 13 80 37L94 26V56L80 45C62 67 31 65 18 41Z" fill="${f.colour}"/><path d="M42 25L51 12L65 25M44 55L59 67L68 53" fill="${f.colour}"/><path d="M71 29Q62 40 71 51" stroke="#405F60" stroke-width="2" fill="none"/><circle cx="34" cy="36" r="3.4" fill="#263E3D"/><path d="M21 44Q25 46 28 43" stroke="#263E3D" fill="none"/>`);}
function furnishingIcon34(t){
 const brown='#98684B',cream='#ECDDBD',green='#628675',dark='#374D46',gold='#CC9A4D';
 const pics={
 plant:`<path d="M34 46H66L62 73H39Z" fill="#BD795C"/><path d="M50 48V18" stroke="${dark}" stroke-width="3"/><ellipse cx="39" cy="30" rx="16" ry="7" transform="rotate(30 39 30)" fill="${green}"/><ellipse cx="61" cy="20" rx="17" ry="8" transform="rotate(-30 61 20)" fill="#8FA97A"/>`,
 lamp:`<path d="M30 12H69L81 40H19Z" fill="${cream}"/><path d="M50 40V68M33 69H67" stroke="${dark}" stroke-width="5"/>`,
 chairs:`<rect x="22" y="10" width="56" height="35" rx="8" fill="${brown}"/><rect x="19" y="42" width="62" height="10" rx="3" fill="${cream}"/><path d="M27 49V72M73 49V72" stroke="${brown}" stroke-width="6"/>`,
 rug:`<path d="M20 15H80L91 63H9Z" fill="${cream}"/><path d="M26 25H74L80 54H20Z" fill="${green}"/><path d="M30 35L40 45L50 35L60 45L70 35" fill="none" stroke="${cream}" stroke-width="4"/>`,
 art:`<rect x="21" y="7" width="58" height="66" rx="3" fill="${brown}"/><rect x="27" y="13" width="46" height="54" fill="${cream}"/><circle cx="42" cy="30" r="10" fill="${gold}"/><path d="M27 58L47 35L73 60V67H27Z" fill="${green}"/>`,
 planter:`<path d="M14 43H87L81 68H19Z" fill="${brown}"/><path d="M30 44V17M51 44V13M72 44V18" stroke="${green}" stroke-width="5"/><ellipse cx="24" cy="24" rx="12" ry="6" fill="${green}"/><ellipse cx="62" cy="25" rx="15" ry="6" fill="#8FA97A"/><circle cx="51" cy="37" r="6" fill="#C5654D"/>`,
 shelf:`<rect x="20" y="8" width="60" height="63" rx="3" fill="${brown}"/><path d="M25 30H75M25 50H75" stroke="${cream}" stroke-width="4"/><path d="M31 15V28M40 13V28M50 17V28M31 37V48M45 35V48M60 37V48" stroke="${green}" stroke-width="7"/>`,
 coffee:`<ellipse cx="50" cy="31" rx="37" ry="15" fill="${brown}"/><path d="M23 35V64M77 35V64" stroke="${dark}" stroke-width="6"/><ellipse cx="62" cy="26" rx="9" ry="5" fill="${cream}"/>`,
 armchair:`<rect x="23" y="12" width="54" height="43" rx="16" fill="${brown}"/><rect x="26" y="31" width="48" height="25" rx="9" fill="${cream}"/><path d="M20 29V57M80 29V57M28 55V70M72 55V70" stroke="${brown}" stroke-width="8"/>`,
 speaker:`<rect x="27" y="9" width="46" height="62" rx="8" fill="${dark}"/><circle cx="50" cy="49" r="14" fill="#7D8C80"/><circle cx="50" cy="49" r="6" fill="${dark}"/><circle cx="50" cy="23" r="5" fill="${cream}"/>`,
 bed:`<rect x="14" y="14" width="73" height="55" rx="7" fill="${brown}"/><rect x="20" y="21" width="61" height="41" rx="5" fill="${cream}"/><rect x="20" y="37" width="61" height="25" rx="3" fill="${green}"/><rect x="26" y="24" width="20" height="9" rx="4" fill="#FFF8EB"/>`,
 dining:`<rect x="9" y="20" width="82" height="23" rx="10" fill="${brown}"/><path d="M22 41V69M78 41V69" stroke="${dark}" stroke-width="7"/><ellipse cx="50" cy="28" rx="11" ry="6" fill="${cream}"/>`,
 wardrobe:`<rect x="18" y="7" width="64" height="64" rx="5" fill="${brown}"/><path d="M50 9V69" stroke="${dark}" stroke-width="2"/><path d="M44 34V45M56 34V45" stroke="${cream}" stroke-width="3"/>`,
 kitchen:`<rect x="12" y="26" width="76" height="46" rx="5" fill="#A9B7A7"/><rect x="10" y="20" width="80" height="10" rx="5" fill="${dark}"/><ellipse cx="34" cy="20" rx="12" ry="5" fill="${cream}"/><ellipse cx="67" cy="20" rx="12" ry="5" fill="${cream}"/><path d="M50 34V67" stroke="${dark}" stroke-width="2"/>`,
 tvconsole:`<rect x="20" y="8" width="60" height="39" rx="5" fill="${dark}"/><path d="M27 38L45 21L72 38" stroke="${green}" stroke-width="7" fill="none"/><rect x="10" y="53" width="80" height="18" rx="5" fill="${brown}"/>`
 };return lifeSVG34(pics[t]||pics.chairs);
}
function pepperIcon34(){return lifeSVG34('<path d="M45 24Q24 23 25 43T49 64Q71 65 76 42T56 25Z" fill="#C96143"/><path d="M47 28Q44 16 57 9" stroke="#4D7653" stroke-width="6" fill="none"/><path d="M39 33Q33 45 40 51" stroke="#EC9B6D" stroke-width="5" fill="none"/>');}
function shellIcon34(){return lifeSVG34('<path d="M48 66C-3 52 17 9 36 20C42 1 62 5 66 20C89 8 106 52 54 66Z" fill="#D6B592"/><path d="M50 61L31 26M50 61V19M50 61L70 26" stroke="#A47A62" stroke-width="2" fill="none"/>');}
function openLifePanel34(content,tab){LIFE34.tab=tab;openPanel(`<section class="life34">${content}</section>`);panel.classList.add('life-panel34');}
const panel34=openPanel;openPanel=function(html){panel.classList.remove('life-panel34');return panel34(html);};
function lifeNav34(){return `<nav class="life-tabs34" aria-label="Your compound">${LIFE_TABS34.map(([k,n])=>`<button type="button" data-act="lifeTab" data-v="${k}" aria-current="${LIFE34.tab===k?'page':'false'}" class="${LIFE34.tab===k?'selected':''}">${n}</button>`).join('')}</nav>`;}
function requestCard34(k){const r=request34(k),q=REQUESTS34[k][r.stage];const near=neighbourNear34(k),waiting=r.lastDay===S.day;
 return `<article class="life-card34 request34"><span class="life-label34">${esc(CAST[k].name)} · ${Math.min(r.stage,3)}/3 little stories</span><h3>${q?esc(q.title):'You are one of our people.'}</h3><p>${q?esc(q.text):esc(callback34(k))}</p>${q?`<p class="small"><b>${esc(q.goal)}</b></p><p class="small muted">${waiting?'Come back on another day. There is no rush.':'A thank-you: '+esc(q.reward)}</p>${!near?btn('Find '+CAST[k].name,'lifeGo',{v:k},'quiet'):waiting?'':q.test()?btn('Help out','lifeRequest',{k},'primary'):'<span class="life-label34">Not ready yet · keep exploring</span>'}`:k==='ada'&&life34().visitsUnlocked?home34()?btn('Invite Ada to the veranda','lifeVisit',{},'primary'):btn('Walk home to invite Ada','lifeGo',{v:'home'},'primary'):''}</article>`;
}
function todayHTML34(){const l=life34(),d=day34(),age=S.day-l.startDay;
 const title=['Make yourself at home.','A familiar face.','Look what you grew.'][Math.min(age,2)]||'Your pace. Your place.';
 const intro=['A little water, a walk to the shore, something lovely for the flat. Start wherever you like.','Yesterday left a trace. Check the plant, see who is around, and find a new corner for something you love.','With two watered nights, the first peppers are ready. The compound is beginning to know your name.'][Math.min(age,2)];
 const e=evening33();return `<div class="life-hero34"><div><p class="life-kicker">PALM COURT · DAY ${S.day}</p><h2>${title}</h2><p>${intro}</p></div><div class="hero-plant34">${furnishingIcon34('planter')}</div></div><div class="life-chips34"><span>${naira(S.money)} in the purse</span><span>${Object.keys(l.collection).length}/6 fish discovered</span><span>${S.home.storage.length} things in storage</span></div>
 <div class="life-grid34"><button class="life-feature34" data-act="lifeTab" data-v="garden">${pepperIcon34()}<b>${l.crop.stage===3?'Your peppers are ready':l.crop.stage===0?'A seedling from Tunde':d.watered?'Watered, and happy':'Visit the pepper pot'}</b><span>Grow a little something.</span></button><button class="life-feature34" data-act="lifeFish">${fishIcon34(FISH34[0])}<b>${l.catch?'A catch is waiting':'Down by the water'}</b><span>Cast, catch, collect.</span></button><button class="life-feature34" data-act="lifeTab" data-v="market">${furnishingIcon34(offers34()[0])}<b>Five finds for today</b><span>A home that looks like you.</span></button><button class="life-feature34" data-act="lifeTab" data-v="people">${furnishingIcon34('chairs')}<b>Your people</b><span>Small favours. Familiar faces.</span></button></div>
 <div class="life-note34"><b>Today, at your own pace</b><p>${d.caught?'✓':'○'} Make a discovery &nbsp; ${d.watered||d.harvested?'✓':'○'} Tend the garden &nbsp; ${d.helped?'✓':'○'} Help a neighbour</p><span class="small">Nothing expires when you close the game. Plants wait for you.</span></div>
 ${e&&!e.completed?`<div class="life-note34"><b>Your first evening is still here.</b><p class="small">Move in, cook and host at your pace.${e.done?.cook&&!S.dishes.length&&!e.done?.host?' Cook another dish before the housewarming.':''}</p>${btn('Continue the first evening','firstEvening34',{},'quiet')}</div>`:''}
 ${e&&e.completed&&e.plan&&S.day===e.finishedDay+1?`<div class="life-note34"><b>${esc(PLANS33[e.plan].title)}</b><p class="small">${esc(PLANS33[e.plan].detail.replace('Tomorrow morning','This morning'))}</p></div>`:''}
 <div class="actions">${btn('Back to the compound','close',{},'primary')}${btn('Rest until tomorrow','sleep',{},'quiet')}</div>`;
}
function almanacHTML34(){const l=life34();return `<p class="life-kicker">THE COMPOUND ALMANAC</p><h2>Look what you found.</h2><p>Every discovery stays here, even when you cook, sell or release it.</p><div class="life-grid34 almanac34">${FISH34.map(f=>{const c=l.collection[f.id];return `<article class="life-card34 ${c?'':'undiscovered'}">${fishIcon34(f)}<h3>${c?f.name:'A fish to discover'}</h3><p class="small">${c?c.count+' caught · best '+c.best+' cm':'Try the waterfront. Evening brings different chances.'}</p></article>`;}).join('')}<article class="life-card34">${pepperIcon34()}<h3>Veranda peppers</h3><p class="small">${l.crop.harvests} harvests · ${l.crop.harvests*3} peppers grown</p></article><article class="life-card34">${shellIcon34()}<h3>Shore shells</h3><p class="small">${l.shells} kept for making things</p>${btn('Walk to the shore','lifeGo',{v:'shells'},'quiet')}</article></div>`;}
function gardenHTML34(){const c=life34().crop,labels=['A pot with possibilities.','Small leaves. Big plans.','Standing a little taller.','Three bright red peppers.'];return `<p class="life-kicker">YOUR VERANDA GARDEN</p><h2>${labels[c.stage]}</h2><div class="garden-art34 stage${c.stage}">${furnishingIcon34(c.stage===3?'planter':'plant')}</div><div class="growth34" aria-label="Growth stage ${c.stage} of 3">${['Plant','Seedling','Growing','Harvest'].map((x,i)=>`<span class="${i<=c.stage?'grown':''}">${x}</span>`).join('')}</div><p>${c.stage===0?'Tunde has left a seedling. The pot, soil and first plant are a welcome gift.':c.stage===3?'Pick them for the kitchen, a neighbour or the market. Your plant will grow another crop.':c.wateredDay===S.day?'Watered for today. Sleep when you are ready; it will grow in the morning.':'A little water today means new growth tomorrow. It needs two watered nights to fruit.'}</p><p class="small muted">One watering per in-game day. Miss a day? The plant simply waits. Your pot is on the veranda.</p><div class="actions">${!home34()?btn('Walk to your veranda','lifeGo',{v:'garden'},'primary'):c.stage===0?btn('Plant the seedling','lifePlant',{},'primary'):c.stage===3?btn('Harvest 3 peppers','lifeHarvest',{},'primary'):c.wateredDay!==S.day?btn('Water the plant','lifeWater',{},'primary'):'<span class="life-pill34">✓ Watered today</span>'}${btn('Back to the compound','close',{},'quiet')}</div>`;}
function marketHTML34(){const l=life34(),today=offers34();return `<p class="life-kicker">PALM COURT FINDS · MARKET ROAD</p><h2>A little more yours.</h2><p>Five pieces on offer each day. All fifteen return over three days. Purchases go into your home storage.</p><div class="life-chips34"><span>${naira(S.money)} in the purse</span><span>Today’s prices: 25% below Build</span></div>${!market34()?`<div class="life-note34">Browse here, then visit the stall to buy or sell. ${btn('Find the stall','lifeGo',{v:'market'},'quiet')}</div>`:''}<div class="life-grid34">${FINDS34.map(t=>{const available=today.includes(t),bought=l.orders[S.day+':'+t];return `<article class="life-card34 ${available?'':'later34'}">${furnishingIcon34(t)}<span class="life-label34">${available?'TODAY’S FIND':'BACK ANOTHER DAY'}${owned34(t)?' · OWNED':''}</span><h3>${ITEMS[t].name}</h3><p class="small">${ITEMS[t].blurb}</p><b>${naira(available?paid34(t):ITEMS[t].price)}</b>${available?(bought?'<span class="life-pill34">In your storage</span>':`<button class="btn primary block" data-act="lifeBuy" data-t="${t}" ${S.money<paid34(t)?'disabled':''}>${market34()?'Buy for the flat':'Visit to buy'}</button>`):''}</article>`;}).join('')}</div><div class="life-note34"><h3>A little extra for the purse</h3><p class="small">Sell ordinary pantry fish for ₦1,200 or peppers for ₦600. Special catches can be sold directly for their catch price.</p>${['fish','pepper'].map(k=>`<button class="btn" data-act="lifeSell" data-k="${k}" ${haveCount(k)<1?'disabled':''}>Sell one ${k} · ${haveCount(k)} available</button>`).join('')}</div>`;}
function homeHTML34(){if(!home34())return `<p class="life-kicker">FLAT 3</p><h2>Make a space for yourself.</h2><p>Bring a player home to arrange furniture. Your purchases wait safely in storage.</p>${btn('Walk home','lifeGo',{v:'home'},'primary')}`;
 const ix=LIFE34.selection,t=ix===null?null:S.home.storage[ix],selected=S.home.items.find(x=>x.id===LIFE34.selectedItem);
 return `<p class="life-kicker">FLAT 3 · YOUR HOME</p><h2>${t?'Where should it go?':'A room that feels like you.'}</h2><p class="small">${t?'Choose a green space for your '+ITEMS[t].name.toLowerCase()+'. The solid border marks the back wall.':'Choose something from storage, then tap a space. Tap a placed piece to rotate or store it.'}</p><div class="room34" role="group" aria-label="Flat layout, back wall at top and veranda at bottom">${Array.from({length:30},(_,k)=>{const x=k%6,y=Math.floor(k/6),it=itemAt(x,y),ok=t&&fitsEditor34(t,x,y,LIFE34.rotation),isStart=it&&it.x===x&&it.y===y;return `<button class="cell34 ${y===4?'veranda':''} ${it?'occupied':''} ${it&&it.id===LIFE34.selectedItem?'chosen':''} ${ok?'can-place':''}" data-act="lifeCell" data-x="${x}" data-y="${y}" aria-label="${y===4?'Veranda':'Row '+(y+1)}, column ${x+1}${it?', '+ITEMS[it.type].name:', empty'}" ${t&&!ok?'disabled':''}>${isStart?furnishingIcon34(it.type):it?'<span>·</span>':'<span>+</span>'}</button>`;}).join('')}</div><p class="life-label34 room-caption34">VERANDA · THE OPEN AIR</p><div class="life-options">${t||selected?btn('Rotate ↻','lifeRotate',{},'quiet'):''}${t?btn('Cancel selection','lifeCancel',{},'quiet'):''}${selected?btn('Put in storage','lifeStore',{},'quiet'):''}${LIFE34.undo?btn('Undo last change','lifeUndo',{},'quiet'):''}</div><h3>In storage · ${S.home.storage.length}</h3><div class="storage34">${S.home.storage.map((v,i)=>`<button data-act="lifeSelect" data-ix="${i}" class="${ix===i?'selected':''}">${furnishingIcon34(v)}<span>${ITEMS[v].name}</span></button>`).join('')||'<p class="small muted">Your first market find or neighbour’s gift will appear here.</p>'}</div>${btn('Browse today’s finds','lifeTab',{v:'market'},'quiet')}${btn('See it in the room','close',{},'primary')}`;
}
function openLife34(tab){if(!S||S.phase!=='play')return;life34();clearFishing34();LIFE34.fish=null;LIFE34.tab=LIFE_TABS34.some(([k])=>k===tab)?tab:'today';
 const pages={today:todayHTML34,almanac:almanacHTML34,garden:gardenHTML34,market:marketHTML34,people:()=>`<p class="life-kicker">YOUR PEOPLE</p><h2>A place with familiar faces.</h2><p>Find your neighbours around the compound. Each has three small stories. Help once per neighbour each day; nobody minds if you take longer.</p>${['tunde','nkechi','ada'].map(requestCard34).join('')}`,home:homeHTML34};
 const html=lifeNav34()+pages[LIFE34.tab]()+`<div class="life-footer34">${btn('Back to the compound','close',{},'quiet')}<span>Saved with your household · Day ${S.day}</span></div>`;openLifePanel34(html,LIFE34.tab);
}
